onClick:
{{
  (async () => {
    const modusWert = 'Später';
    const activeVentil = appsmith.store.activeVentil;
    const programm = appsmith.store.selectedProg || "";
    const bemerkung = inp_Bemerkung.text || "";

    closeModal('Modal_Programm');
    resetWidget('inp_Bemerkung', true);

    // Store-Flag für das einzelne Ventil zurücksetzen
    const btnVal = parseFloat(activeVentil).toFixed(2);
    await storeValue('Ventil_Leer_' + btnVal, false);

    // Speichert lokal in `lokaleBewaesserungData` und setzt `lastUpdate`
    await Data_Helper.speichereEintrag(activeVentil, modusWert, programm, bemerkung);

    // Google Sheets im Hintergrund aktualisieren (OHNE await Stammdaten.run())
    try {
      const daten = appsmith.store.lokaleBewaesserungData || [];
      const existIndex = daten.findIndex(r => String(r.Ventil).trim() === String(activeVentil).trim() && String(r.Status || "").toLowerCase() !== "fertig");

      if (existIndex !== -1 && daten[existIndex].rowIndex !== undefined) {
        await Bewaesserung_Update_Eintrag.run({
          "realRowIndex": daten[existIndex].rowIndex,
          "programm": programm,
          "modus": modusWert,
          "zeitstempel": daten[existIndex].Zeitstempel,
          "bemerkung": bemerkung
        });
      } else {
        await Bewaesserung_Speichern.run({
          "ventilName": activeVentil,
          "programm": programm,
          "modus": modusWert,
          "zeitstempel": moment().format('DD.MM.YYYY HH:mm'),
          "bemerkung": bemerkung,
          "stammdaten": Stammdaten.data 
        });
      }

      const stammdatenArray = Stammdaten.data || [];
      const targetIdx = stammdatenArray.findIndex(r => 
        String(r.Ventil_Links || "").trim() === String(activeVentil).trim() || 
        String(r.Ventil_Rechts || "").trim() === String(activeVentil).trim()
      );

      // Backend-Update anstoßen, aber die Appsmith-Oberfläche NICHT neu laden
      Bewaesserung_Update_Eintrag.run(); 
      Stammdaten_Update.run({ "neuerStatus": "", "targetIndex": targetIdx });

    } catch (e) {
      showAlert("Fehler beim Speichern: " + e.message, "error");
    }
  })()
}}
